    // Check if the end node is reached
    if (x == end && y == end) return true;
    // Mark the starting point as visited
    for (int neighbor : adjacencyList.getOrDefault(start, new ArrayList<>())) {
        if (neighbor == end) return true;
        // Recursively search for the path through the neighbor
        List<Integer> neighbors = adjacencyList.getOrDefault(neighbor, new ArrayList<>());
        boolean isFound = doDFS(adjacencyList, neighbor, start, x, y);
        if (isFound) return true;
    }
    // If no path is found, mark the starting point as not visited
    return false;
