/**
 * This method calculates the minimum time required to collect all apples in a tree.
 * Each node in the tree has an apple if `hasApple[i]` is true.
 * The method starts from node 0 and returns to node 0.
 * 
 * @param n The number of nodes in the tree.
 * @param edges An array of edges in the tree represented as pairs [parent, child].
 * @param hasApple A boolean array indicating whether each node has an apple.
 * @return The minimum time required to collect all apples.
 */
public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    // Build the graph from edges
    for (int[] edge : edges) {
        int parent = edge[0], child = edge[1];
        graph.get(parent).add(child);
    }

    return dfs(0, -1, graph, hasApple);
}

/**
 * Depth-First Search (DFS) to find the minimum time to collect all apples.
 * 
 * @param node The current node being visited.
 * @param parent The parent node of the current node.
 * @param graph The graph representation of the tree.
 * @param hasApple A boolean array indicating whether each node has an apple.
 * @return The minimum time required to collect all apples starting from the current node.
 */
private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
    int time = 0;

    // Traverse all children of the current node
    for (int child : graph.get(node)) {
        if (child == parent) {
            continue; // Skip the parent node
        }
        time += dfs(child, node, graph, hasApple);

        // If the child has an apple or the child is a common ancestor of the current node's apple and their parent
        if (hasApple[child] || (hasApple[parent] && child != parent)) {
            time += 2; // Adding 2 to account for the round trip
        }
    }

    return time;
}
