        // Find the sum of all elements in the array
        int totalSum = Arrays.stream(nums).sum();
        // Calculate the average of the array elements
        double average = (double) totalSum / n;

        // Check if there is the same integer that evenly divides the total sum
        // Note: The average is an integer, so we need to check if there is an integer factor
        // The average of two non-empty arrays will be the average of their sums divided by their lengths
