public class Solution {
    public int findMinFibonacciNumbers(int k) {
        Collection<Long> fibFence = createFibonacciFence().stream().collect(Collectors.toList());
        int count = 0;
        for (int i = fibFence.size() - 1; i >= 0 && k > 0; i--) {
            while (k >= fibFence.get(i)) {
                k -= fibFence.get(i);
                count++;
            }
        }
        return count;
    }

    private Collection<Long> createFibonacciFence() {
        Collection<Long> fibonacciNumbers = new java.util.ArrayList<>();
        fibonacciNumbers.add(1L);
        fibonacciNumbers.add(1L);
        long x = 1;
        long y = 1;
        long nextFib;
        while (true) {
            nextFib = x + y;
            if (nextFib > Integer.MAX_VALUE) break;
            fibonacciNumbers.add(nextFib);
            x = y;
            y = nextFib;
        }
        return fibonacciNumbers;
    }
