import java.math.BigInteger;

public class SquareSumSolver {

    /**
     * Calculates the minimum number of perfect square numbers that sum up to the given integer n.
     * 
     * @param n The target integer.
     * @return The minimum number of perfect square numbers.
     */
    public static int minPerfectSquareSum(int n) {
        int maxSquareRoot = (int) Math.sqrt(n);
        int[] dp = new int[n + 1];

        // Base case: two 1s can sum up to the number itself
        Arrays.fill(dp, 2);

        // Fill the dp array
        for (int i = 1; i <= maxSquareRoot; i++) {
            long square = (long) i * i;
            for (int j = square; j <= n; j++) {
                dp[j] = Math.min(dp[j], dp[j - square] + 1);
            }
        }

        // The result is dp[n]
        return dp[n];
    }

