public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty.");
    }

    String[] words = s.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        StringBuilder reversedWord = new StringBuilder(words[i]);
        int left = 0, right = reversedWord.length() - 1;
        while (left < right) {
            char temp = reversedWord.charAt(left);
            reversedWord.setCharAt(left, reversedWord.charAt(right));
            reversedWord.setCharAt(right, temp);
            left++;
            right--;
        }
        words[i] = reversedWord.toString();
    }

    return String.join(" ", words);
}
